using System.ComponentModel.DataAnnotations;

namespace JaeZoo.Server.Models.Mls;

// The server is the MLS Delivery Service (RFC 9420, section 4): it stores and orders
// opaque MLS messages and never holds decryption keys. See docs/MLS_ARCHITECTURE.md.

/// <summary>A user's device = one MLS leaf. Bound to the login session it was registered from.</summary>
public sealed class UserDevice
{
    /// <summary>Device id generated by the client (part of the MLS leaf identity userId||deviceId).</summary>
    public Guid Id { get; set; }

    public Guid UserId { get; set; }

    /// <summary>Login session currently bound to this device (revoking the device ends it).</summary>
    public Guid? SessionId { get; set; }

    [MaxLength(128)] public string Name { get; set; } = string.Empty;
    [MaxLength(64)] public string Platform { get; set; } = string.Empty;
    [MaxLength(32)] public string ClientVersion { get; set; } = string.Empty;

    /// <summary>Ed25519 public key of the leaf (informational; MLS itself authenticates leaves).</summary>
    public byte[] SignaturePublicKey { get; set; } = Array.Empty<byte>();

    public DateTime CreatedAt { get; set; } = DateTime.UtcNow;
    public DateTime LastSeenAt { get; set; } = DateTime.UtcNow;
    public DateTime? RevokedAt { get; set; }

    [MaxLength(32)] public string? RevokeReason { get; set; }
}

/// <summary>Published KeyPackage of a device. One-time ones are deleted on claim; the last-resort one is kept.</summary>
public sealed class MlsKeyPackage
{
    public Guid Id { get; set; } = Guid.NewGuid();
    public Guid UserId { get; set; }
    public Guid DeviceId { get; set; }
    public byte[] Data { get; set; } = Array.Empty<byte>();
    public bool IsLastResort { get; set; }
    public DateTime CreatedAt { get; set; } = DateTime.UtcNow;
}

public enum MlsConversationKind
{
    Direct = 1,
    Group = 2,
}

/// <summary>Maps a conversation (direct dialog or group chat) to its MLS group and current epoch.</summary>
public sealed class MlsGroupState
{
    /// <summary>MLS group id (16 random bytes chosen by the creating client, stored as Guid).</summary>
    public Guid Id { get; set; }

    public MlsConversationKind Kind { get; set; }
    public Guid? DialogId { get; set; }
    public Guid? GroupChatId { get; set; }

    /// <summary>Current epoch as accepted by the delivery service. Commits must be built on exactly this epoch.</summary>
    public long Epoch { get; set; }

    public DateTime CreatedAt { get; set; } = DateTime.UtcNow;
    public DateTime UpdatedAt { get; set; } = DateTime.UtcNow;
}

/// <summary>Server's view of which device leaves are in a group (as declared by accepted commits).</summary>
public sealed class MlsGroupMember
{
    public Guid GroupId { get; set; }
    public Guid DeviceId { get; set; }
    public Guid UserId { get; set; }
    public long AddedAtEpoch { get; set; }
}

public enum MlsEventKind
{
    Commit = 1,
    Message = 2,
    MessageEdited = 3,
    MessageDeleted = 4,
}

/// <summary>
/// Ordered per-group log. Devices sync by <see cref="Id"/> cursor and process events in order,
/// which is what stateful MLS processing needs. Message bodies live in the message tables.
/// </summary>
public sealed class MlsGroupEvent
{
    public long Id { get; set; }
    public Guid GroupId { get; set; }
    public MlsEventKind Kind { get; set; }

    /// <summary>For commits: epoch the commit was built on (it produces Epoch + 1). For messages: encryption epoch.</summary>
    public long Epoch { get; set; }

    public Guid? MessageId { get; set; }
    public Guid SenderUserId { get; set; }
    public Guid? SenderDeviceId { get; set; }

    /// <summary>Commit bytes (MLS PublicMessage). Null for message events.</summary>
    public byte[]? Payload { get; set; }

    public DateTime CreatedAt { get; set; } = DateTime.UtcNow;
}

/// <summary>Welcome for one device, kept until the device acknowledges it.</summary>
public sealed class MlsWelcome
{
    public Guid Id { get; set; } = Guid.NewGuid();
    public Guid GroupId { get; set; }
    public Guid TargetUserId { get; set; }
    public Guid TargetDeviceId { get; set; }

    /// <summary>Epoch the joiner starts at.</summary>
    public long Epoch { get; set; }

    /// <summary>Event id of the commit that created this welcome; the joiner syncs after it.</summary>
    public long CommitEventId { get; set; }

    public byte[] Data { get; set; } = Array.Empty<byte>();
    public DateTime CreatedAt { get; set; } = DateTime.UtcNow;
}

/// <summary>
/// Latest GroupInfo a member published (RFC 9420 §12.4.3: ratchet tree + external public key, signed by the
/// member). Public data: lets a participant's new device join by External Commit when no member is online.
/// Valid only while <see cref="Epoch"/> equals the group's current epoch.
/// </summary>
public sealed class MlsGroupInfo
{
    public Guid GroupId { get; set; }
    public long Epoch { get; set; }
    public Guid PublishedByDeviceId { get; set; }
    public byte[] Data { get; set; } = Array.Empty<byte>();
    public DateTime UpdatedAt { get; set; } = DateTime.UtcNow;
}
